# Workboard

Requires Node.js 22.22.1. No external dependencies or installation step are needed.

```sh
npm start
```

The server binds to `0.0.0.0` on `PORT` (default `8080`). `DB_PATH` selects
the persistent SQLite file (default `data/workboard.sqlite`); its parent
directory is created automatically. Use the same file across restarts.

```sh
PORT=8080 DB_PATH=/tmp/workboard.sqlite npm start
npm test
```

Open `/` to create and open projects. Each project page supports creating
tasks, saving their completion state, and filtering by All, Open, or Completed.
Projects and tasks retain creation order and persist in the configured database.
`GET /health` returns
`{"status":"ok"}`. The integration test uses an isolated temporary database
and verifies validation, project ownership, completion updates, ordering,
HTTP routes, and persistence across a
server restart.
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

async function startServer(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', (data) => { errors += data; });
  try {
    const port = await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(new Error(`Server startup timed out: ${errors}`)), 5000);
      child.once('error', (error) => { clearTimeout(timeout); reject(error); });
      child.once('exit', (code) => { clearTimeout(timeout); reject(new Error(`Server exited (${code}): ${errors}`)); });
      child.stdout.on('data', (data) => {
        output += data;
        const match = output.match(/listening on port (\d+)/);
        if (match) { clearTimeout(timeout); resolve(match[1]); }
      });
    });
    return {
      url: `http://127.0.0.1:${port}`,
      async stop() {
        if (child.exitCode !== null) return;
        const exited = once(child, 'exit');
        child.kill('SIGTERM');
        await exited;
      },
    };
  } catch (error) {
    child.kill();
    throw error;
  }
}

test('projects validate names, retain creation order, and persist across server restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const databasePath = join(directory, 'nested', 'projects.sqlite');
  let server;
  try {
    server = await startServer(databasePath);
    const request = (path, options) => fetch(`${server.url}${path}`, options);
    const create = (name) => request('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    const health = await request('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    assert.deepEqual(await (await request('/api/projects')).json(), []);
    for (const name of ['', ' \t\n ', null, 42]) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await request('/api/projects')).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('<script> & another project')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await request('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await request(`/api/projects/${first.id}`)).json(), first);
    assert.equal((await request('/api/projects/999999')).status, 404);
    assert.equal((await request('/api/projects/99999999999999999999')).status, 404);
    const malformed = await request('/api/projects', { method: 'POST', body: '{broken' });
    assert.equal(malformed.status, 400);
    const home = await request('/');
    assert.equal(home.status, 200);
    assert.match(await home.text(), /<h1>Workboard<\/h1>/);
    assert.equal((await request(`/projects/${first.id}`)).status, 200);
    assert.equal((await request('/app.js')).status, 200);
    assert.equal((await request('/style.css')).status, 200);
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual(await (await request('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await request(`/api/projects/${first.id}`)).json(), first);
    const third = await (await create('Third')).json();
    assert.ok(third.id > second.id);
  } finally {
    await server?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('tasks validate titles, belong to projects, and preserve completion across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let server;
  try {
    server = await startServer(databasePath);
    const request = (path, method = 'GET', body) => fetch(`${server.url}${path}`, {
      method,
      ...(body === undefined ? {} : {
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      }),
    });
    const firstProject = await (await request('/api/projects', 'POST', { name: 'First' })).json();
    const secondProject = await (await request('/api/projects', 'POST', { name: 'Second' })).json();
    const firstPath = `/api/projects/${firstProject.id}/tasks`;
    const secondPath = `/api/projects/${secondProject.id}/tasks`;
    assert.deepEqual(await (await request(firstPath)).json(), []);
    for (const title of ['', ' \t\n ', null, 42]) {
      const invalid = await request(firstPath, 'POST', { title });
      assert.equal(invalid.status, 400);
      assert.deepEqual(await invalid.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await (await request(firstPath)).json(), []);
    const created = await request(firstPath, 'POST', { title: '  First task  ' });
    assert.equal(created.status, 201);
    const first = await created.json();
    assert.equal(first.title, 'First task');
    assert.equal(first.completed, false);
    const second = await (await request(firstPath, 'POST', { title: '<script> & task' })).json();
    assert.ok(second.id > first.id);
    assert.deepEqual(await (await request(firstPath)).json(), [first, second]);
    assert.deepEqual(await (await request(secondPath)).json(), []);
    assert.equal((await request(`${secondPath}/${first.id}`, 'PATCH', { completed: true })).status, 404);
    assert.equal((await request('/api/projects/999999/tasks', 'POST', { title: 'Unknown' })).status, 404);
    for (const completed of [null, 1, 'true']) {
      assert.equal((await request(`${firstPath}/${first.id}`, 'PATCH', { completed })).status, 400);
    }
    assert.equal((await request(`${firstPath}/99999999999999999999`, 'PATCH', { completed: true })).status, 404);
    assert.deepEqual(await (await request(firstPath)).json(), [first, second]);
    const completedResponse = await request(`${firstPath}/${first.id}`, 'PATCH', { completed: true });
    assert.equal(completedResponse.status, 200);
    const completed = await completedResponse.json();
    assert.deepEqual(completed, { ...first, completed: true });
    const other = await (await request(secondPath, 'POST', { title: 'Other project task' })).json();
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual(await (await request(firstPath)).json(), [completed, second]);
    assert.deepEqual(await (await request(secondPath)).json(), [other]);
    assert.equal((await request(`/projects/${firstProject.id}`)).status, 200);
    const reopened = await request(`${firstPath}/${first.id}`, 'PATCH', { completed: false });
    assert.deepEqual(await reopened.json(), first);
    await server.stop();
    server = await startServer(databasePath);
    assert.deepEqual(await (await request(firstPath)).json(), [first, second]);
  } finally {
    await server?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Unable to complete request');
  return result;
}

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

function projectRow(project, onArchive, showError) {
  const row = element('li', '', { 'data-testid': 'project-row', class: 'project-row' });
  const button = element('button', 'Open project', { type: 'button' });
  button.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const details = element('div', '', { class: 'project-details' });
  details.append(element('span', project.name), element('span', `${project.completedCount}/${project.totalCount} completed`, {
    'data-testid': 'project-summary', class: 'project-summary',
  }));
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project', { type: 'button' });
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      onArchive();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  const actions = element('div', '', { class: 'project-actions' });
  actions.append(button, archive);
  row.append(details, actions);
  return row;
}

async function showProjects() {
  const projects = await api('/api/projects');
  const heading = element('h1', 'Workboard');
  const intro = element('p', 'A place for your projects.', { class: 'intro' });
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', '', { id: 'project-name', name: 'name', type: 'text' });
  const submit = element('button', 'Create project', { type: 'submit' });
  const alert = element('p', '', { role: 'alert', class: 'alert' });
  alert.hidden = true;
  const list = element('ul', '', { class: 'projects', 'aria-label': 'Projects' });
  const empty = element('p', 'No projects yet. Create your first project above.', { class: 'empty' });
  const filter = element('select', '', { id: 'project-filter' });
  for (const value of ['Active', 'Archived']) filter.append(element('option', value, { value }));
  const filterControls = element('div', '', { class: 'project-filter' });
  filterControls.append(element('label', 'Project filter', { for: 'project-filter' }), filter);
  function showError(message) {
    alert.textContent = message;
    alert.hidden = false;
  }
  function renderProjects() {
    const visible = projects.filter((project) => project.archived === (filter.value === 'Archived'));
    list.replaceChildren(...visible.map((project) => projectRow(project, renderProjects, showError)));
    empty.textContent = filter.value === 'Archived' ? 'No archived projects.' : 'No active projects. Create a project above.';
    empty.hidden = visible.length > 0;
  }
  filter.addEventListener('change', renderProjects);
  renderProjects();
  form.append(label, input, submit);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    if (!input.value.trim()) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    submit.disabled = true;
    try {
      const project = await api('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      projects.push(project);
      renderProjects();
      input.value = '';
      input.focus();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    } finally {
      submit.disabled = false;
    }
  });
  app.replaceChildren(heading, intro, form, alert, element('h2', 'Projects'), filterControls, empty, list);
}

async function showProject(id) {
  const back = element('button', 'Projects', { type: 'button', class: 'back' });
  back.addEventListener('click', () => { window.location.href = '/'; });
  app.replaceChildren(back);
  const project = await api(`/api/projects/${id}`);
